创建一个git仓库git init
git add (.) 提交到暂存区
git commit -m &lt;&gt;
git log &lt;--stat&gt;
git diff &lt;commit-id&gt;
git reset --hard &lt;commit-id&gt;
git checkout &lt;commit-id&gt;
git branch
git checkout -b develop
$master git merge develop
git config修改某些属性git config --global &lt;properity&gt; &lt;value&gt;
eg:
git config --global user.namegit config --global user.emailgit config --global http.sslverify false 关闭验证ssl证书git config --global http.sslBackend schannel 

查看属性git config --list --show-origin
git clone携带参数eg:git -c http.sslVerify=false clone &lt;URL&gt;
本地仓库和远程仓库绑定(远程分支)git remote remove origin
git remote add origin &quot;https://github.com/LosLiSang/loslisang.github.io.git&quot;
参考迷途小书童的Note迷途小书童的Note (xugaoxiang.com)

题目描述给定一个单链表 L 的头节点 head ，单链表 L 表示为：
L0 → L1 → … → Ln - 1 → Ln
请将其重新排列后变为：
L0 → Ln → L1 → Ln - 1 → L2 → Ln - 2 → …
不能只是单纯的改变节点内部的值，而是需要实际的进行节点交换。 题解解法一：暴力解第i次循环都把最后一个节点移动到第2*i-1个节点后面，当然不是用for循环，只是代码运行的时候链表内部是这样的过程。 记itr为从前往后遍历的节点，只要itr.next不为null，就一直做以下循环
找到最后一个节点的前一个节点记为pre，最后一个节点记为last &#x3D; pre.next 把最后一个节点删除，插入到第itr的后面 令itr前移动两个单位itr &#x3D; itr.next.next
步骤2的Code pre.next = last.next;last.next = itr.next;itr.next = last
代码class Solution &#123; public ListNode lastPre(ListNode head)&#123; ListNode itr = head; while (itr.next.next != null) &#123; itr = itr.next; &#125; return itr; &#125; public void reorderList(ListNode head) &#123; ListNode itr = head; while(itr != null &amp;&amp; itr.next != null)&#123; ListNode pre = lastPre(head); ListNode last = pre.next; pre.next = last.next; last.next = itr.next; itr.next = last; itr = itr.next.next; &#125; &#125;&#125;
时间复杂度 $O(N^2)$ 解法二 找中点，拆分链表 倒置后半段链表 合并两段链表
找中点（快慢指针法）eg11-&gt;2-&gt;3-&gt;4 fast:1 slow:1 fast:3 slow:2 fast.next.next为null，终止循环 那么中点就记为mid &#x3D; slow.next 为 3 eg21-&gt;2-&gt;3-&gt;4-&gt;5 fast:1 slow:1 fast:3 slow:2 fast:5 slow:3 fast.next为null，终止循环 那么中点就记为mid &#x3D; slow.next 为 4 拆分链表，slow.next &#x3D; null; public ListNode getMid(ListNode head)&#123; ListNode slow = head, fast = head; while(fast != null &amp;&amp; fast.next != null)&#123; slow = slow.next; fast = fast.next.next; &#125; return slow;&#125;
倒置链表记后半段链表为back，前半段链表为front 倒置链表使用前插法 public ListNode reverse(ListNode head)&#123; ListNode itr = head; ListNode dummyHead = new ListNode(); while(itr != null)&#123; ListNode temp = itr.next; itr.next = dummyHead.next; dummyHead.next = itr; itr = temp; &#125; return dummyHead.next;&#125;
合并链表public ListNode merge (ListNode l1, ListNode l2) &#123; ListNode head = l1; while(l2 != null &amp;&amp; l1 != null)&#123; ListNode l1Next = l1.next; l1.next = l2; l2 = l2.next; l1.next.next = l1Next; l1 = l1.next.next; &#125; return head;&#125;
总结 链表的赋值，其实和变量交换很类似，都是需要备份的。 封装好功能的函数，远远比一整段写出来的代码要更好理解！！ 不用害怕定义变量，但是前提是你要知道这个变量是用来做什么的

给你一个字符串 s ，你需要将它分割成一个或者更多的 平衡 子字符串。比方说，s &#x3D;&#x3D; “ababcc” 那么 (“abab”, “c”, “c”) ，(“ab”, “abc”, “c”) 和 (“ababcc”) 都是合法分割，但是 (“a”, “bab”, “cc”) ，(“aba”, “bc”, “c”) 和 (“ab”, “abcc”) 不是，不平衡的子字符串用粗体表示。请你返回 s 最少 能分割成多少个平衡子字符串。
样例:
输入：s &#x3D; “fabccddg”输出：3解释：我们可以将 s 分割成 3 个子字符串：(“fab, “ccdd”, “g”) 或者 (“fabc”, “cd”, “dg”) 。
按照动态规划的思路来看, 把问题分割成一个个的子问题 假设dp[i] 表示s[i..]平衡子字符串的最少个数, 那么dp[i-1] &#x3D; min(dp[i] + 1, if 可以得到平衡子字符串 dp[i+1], dp[i+2], .. dp[n]) 问题在于如何判断s[i..j] 是否是一个平衡子字符串 实现一个check函数 fn check(chars: &amp;Vec&lt;char&gt;, i: usize, j: usize) -&gt; bool&#123; let mut cnt = HashMap::new(); for k in i..j&#123; *cnt.entry(chars[k]).or_insert(0) += 1; &#125; cnt.values().max() == cnt.values().min()&#125;
代码 use std::collections::&#123;HashMap&#125;;pub struct Solution;impl Solution &#123; pub fn minimum_substrings_in_partition(s: String) -&gt; i32 &#123; fn check(chars: &amp;Vec&lt;char&gt;, i: usize, j: usize) -&gt; bool&#123; let mut cnt = HashMap::new(); for k in i..j&#123; *cnt.entry(chars[k]).or_insert(0) += 1; &#125; cnt.values().max() == cnt.values().min() &#125; let len = s.len(); let mut dp:Vec&lt;i32&gt; = (0..len as i32 +1).collect(); let chars: Vec&lt;char&gt; = s.chars().collect(); for i in 1..len+1&#123; dp[i] = dp[i].min(dp[i-1] + 1); for j in 0..i&#123; if check(&amp;chars, i, j)&#123; dp[i] = dp[i].min(dp[j]); &#125; &#125; &#125; dp[len] &#125;&#125;
但是使用check函数会超时 进一步优化 use std::collections::HashMap;impl Solution &#123; pub fn minimum_substrings_in_partition(s: String) -&gt; i32 &#123; let len = s.len(); let mut dp: Vec&lt;i32&gt; = (0..len as i32 + 1).collect(); let chars: Vec&lt;char&gt; = s.chars().collect(); for i in 1..len &#123; let mut cnt = HashMap::new(); for j in (0..i+1).rev() &#123; *cnt.entry(chars[j]).or_insert(0) += 1; if cnt.values().max() == cnt.values().min() &#123; dp[i+1] = dp[i+1].min(dp[j] + 1); &#125; &#125; &#125; dp[len] &#125;&#125;
